document.addEventListener("DOMContentLoaded", function () {
  const menuToggle = document.querySelector(".menu-toggle");
  const mainMenu = document.querySelector(".main-menu");
  const submenuParents = document.querySelectorAll(".has-submenu");

/* ===== Menú móvil ===== */
if (menuToggle && mainMenu) {

  let savedScrollPosition = 0;

  function openMobileMenu() {
    savedScrollPosition = window.scrollY || window.pageYOffset;

    menuToggle.setAttribute("aria-expanded", "true");
    mainMenu.classList.add("is-open");

    document.body.classList.add("menu-open");
    document.documentElement.classList.add("menu-open");

    document.body.style.top = "-" + savedScrollPosition + "px";

    mainMenu.scrollTop = 0;
  }

  function closeMobileMenu() {
    menuToggle.setAttribute("aria-expanded", "false");
    mainMenu.classList.remove("is-open");

    document.body.classList.remove("menu-open");
    document.documentElement.classList.remove("menu-open");

    document.body.style.top = "";

    window.scrollTo(0, savedScrollPosition);
  }

  menuToggle.addEventListener("click", function (e) {
    e.preventDefault();
    e.stopPropagation();

    const isOpen = mainMenu.classList.contains("is-open");

    if (isOpen) {
      closeMobileMenu();
    } else {
      openMobileMenu();
    }
  });

  /* Regresar al estado normal si cambia a escritorio */
  window.addEventListener("resize", function () {
    if (window.innerWidth > 920 && mainMenu.classList.contains("is-open")) {
      closeMobileMenu();
    }
  });
}

  /* ===== Submenús en móvil ===== */
  submenuParents.forEach(function (item) {
    const trigger = item.querySelector(":scope > a");
    if (!trigger) return;

    trigger.addEventListener("click", function (e) {
      if (window.innerWidth <= 920) {
        const directSubmenu = item.querySelector(":scope > .submenu");
        if (!directSubmenu) return;

        e.preventDefault();

        const parentList = item.parentElement;
        const siblingItems = parentList.querySelectorAll(":scope > .has-submenu");
        const wasOpen = item.classList.contains("is-open");

        siblingItems.forEach(function (sibling) {
          if (sibling !== item) sibling.classList.remove("is-open");
        });

        item.classList.toggle("is-open", !wasOpen);
      }
    });
  });

  /* ===== Sliders duo ===== */
  const sliders = document.querySelectorAll(".duo-slider");

  sliders.forEach(function (slider) {
    const track = slider.querySelector(".duo-slider-track");
    const prevBtn = slider.querySelector(".duo-prev");
    const nextBtn = slider.querySelector(".duo-next");
    const slides = slider.querySelectorAll(".duo-slide");

    if (!track || !slides.length) return;

    let currentIndex = 0;
    const total = slides.length;

    function itemsPerView() {
      return 1;
    }

    function maxIndex() {
      return Math.max(0, total - itemsPerView());
    }

    function updateSlider() {
      const perView = itemsPerView();
      const slideWidth = 100 / perView;

      slides.forEach(function (slide) {
        slide.style.flex = "0 0 " + slideWidth + "%";
        slide.style.maxWidth = slideWidth + "%";
      });

      if (currentIndex > maxIndex()) currentIndex = maxIndex();

      track.style.transform = "translateX(-" + currentIndex * slideWidth + "%)";

      if (prevBtn) prevBtn.disabled = currentIndex <= 0;
      if (nextBtn) nextBtn.disabled = currentIndex >= maxIndex();
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", function () {
        currentIndex = Math.max(0, currentIndex - 1);
        updateSlider();
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", function () {
        currentIndex = Math.min(maxIndex(), currentIndex + 1);
        updateSlider();
      });
    }

    window.addEventListener("resize", updateSlider);
    updateSlider();
  });

  /* ===== Carrusel 3D general ===== */
  const stackCarousels = document.querySelectorAll(".stack-carousel");

  stackCarousels.forEach(function (carousel) {
    const slides = Array.from(carousel.querySelectorAll(".stack-slide"));
    const prevBtn = carousel.querySelector(".stack-prev");
    const nextBtn = carousel.querySelector(".stack-next");

    if (!slides.length) return;

    let current = 0;

    function updateStackCarousel(direction) {
      slides.forEach(function (slide) {
        slide.classList.remove("is-active", "is-prev", "is-next", "slide-from-left", "slide-from-right");
      });

      const total = slides.length;
      const prev = (current - 1 + total) % total;
      const next = (current + 1) % total;

      slides[current].classList.add("is-active");
      slides[prev].classList.add("is-prev");
      slides[next].classList.add("is-next");

      if (direction === "next") slides[current].classList.add("slide-from-right");
      if (direction === "prev") slides[current].classList.add("slide-from-left");
    }

    if (prevBtn) {
      prevBtn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        current = (current - 1 + slides.length) % slides.length;
        updateStackCarousel("prev");
      });
    }

    if (nextBtn) {
      nextBtn.addEventListener("click", function (e) {
        e.preventDefault();
        e.stopPropagation();
        current = (current + 1) % slides.length;
        updateStackCarousel("next");
      });
    }

    updateStackCarousel();
  });

  /* ===== Reveal + Scroll items ===== */
  const animatedItems = document.querySelectorAll(".reveal-section, .scroll-item");

  function showAnimatedItem(item) {
    item.classList.add("is-visible");
  }

  if ("IntersectionObserver" in window && animatedItems.length) {
    const animationObserver = new IntersectionObserver(function (entries, observer) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          showAnimatedItem(entry.target);
          observer.unobserve(entry.target);
        }
      });
    }, {
      threshold: 0.05,
      rootMargin: "0px 0px 120px 0px"
    });

    animatedItems.forEach(function (item) {
      if (item.classList.contains("reveal-hero")) {
        showAnimatedItem(item);
      } else {
        animationObserver.observe(item);
      }
    });

    setTimeout(function () {
      animatedItems.forEach(showAnimatedItem);
    }, 900);
  } else {
    animatedItems.forEach(showAnimatedItem);
  }
});
